parameters.inputSchema:
 {
  "type": "object",
  "properties": {
    "role_signal": {
      "type": "string",
      "description": "One sentence: what this role most needs from a candidate CV."
    },
    "project_order": {
      "type": "array",
      "items": { "type": "string" },
      "description": "All project titles from CV ordered by relevance to this role, most relevant first. Use exact titles as they appear in the CV."
    },
    "segments": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique slug. Examples: profile_summary, seace_bullet_1, pdf_bullet_2, skills_data_engineering, skills_frontend"
          },
          "segment_type": {
            "type": "string",
            "enum": ["profile_summary", "bullet", "skills_subcategory"]
          },
          "original": {
            "type": "string",
            "description": "Exact verbatim text of this segment as it appears in the CV. Must be copy-pasteable."
          },
          "classification": {
            "type": "string",
            "enum": ["DIREKT", "TRANSFERABEL", "DISTRAKTOR"]
          },
          "action": {
            "type": "string",
            "enum": ["KEEP", "REPLACE", "SHORTEN", "REMOVE"]
          },
          "reasoning": {
            "type": "string",
            "description": "Max 12 words explaining the classification."
          },
          "priority_rank": {
            "type": "integer",
            "description": "1 = most relevant to this role."
          },
          "priority_score": { 
            "type": "number", 
            "description": "0.0–1.0 relevance score." 
          },
          "output_word_budget": { 
            "type": "integer", 
            "description": "Target word count after editing. 0 if REMOVE." 
          },
          "output_word_max": { 
            "type": "integer", 
            "description": "Hard ceiling. output_word_budget × 1.2. 0 if REMOVE." 
          }
        },
        "required": ["id", "segment_type", "original", "classification", "action", "reasoning", "priority_rank", "priority_score", "output_word_budget", "output_word_max"]
      }
    }
  },
  "required": ["role_signal", "project_order", "segments"]
}

parameters.jsCode:
const data = $('Classifier').first().json.output;
const segments = data.segments;
const projectOrder = data.project_order;
const roleSignal = data.role_signal;

// Enforce action rules deterministically
const enforced = segments.map(seg => {
  let finalAction = seg.action;

  // Rule 1: DISTRAKTOR -> always REMOVE
  if (seg.classification === 'DISTRAKTOR') {
    finalAction = 'REMOVE';
  }

  // Rule 2: TRANSFERABEL -> never REMOVE, downgrade to SHORTEN
  if (seg.classification === 'TRANSFERABEL' && seg.action === 'REMOVE') {
    finalAction = 'SHORTEN';
  }

  // Rule 3: KEEP with no change needed -> mark as skip
  if (finalAction === 'KEEP') {
    finalAction = 'SKIP';
  }

  return { ...seg, finalAction };
});

// Separate segments that need instructions from those that don't
const toEdit = enforced.filter(s => s.finalAction !== 'SKIP');
const toSkip = enforced.filter(s => s.finalAction === 'SKIP');

// Build the constraint block for the Generator
const constraintLines = toEdit.map(s => {
  const preview = s.original.length > 80 
    ? s.original.substring(0, 80) + '...' 
    : s.original;
  return `[${s.finalAction}] ${s.id} (${s.classification}) — REWRITE to ≤${s.output_word_max} words\nOriginal (${s.output_word_budget > 0 ? s.input_words || '?' : 0} words): "${preview}"\nReason: ${s.reasoning}`;
}).join('\n\n');

// Build project reorder instructions
const reorderInstructions = projectOrder
  .map((title, i) => `${i + 1}. ${title}`)
  .join('\n');

// Budget validation
const target = $('Compute Word Budget').first().json.target_words;
const TOLERANCE = 0.10;

const totalBudgeted = enforced.reduce((sum, seg) => {
  if (seg.finalAction === 'REMOVE' || seg.finalAction === 'SKIP' && seg.output_word_budget === 0) {
    return sum + (seg.finalAction === 'SKIP' ? (seg.output_word_budget || seg.input_words || 0) : 0);
  }
  return sum + (seg.output_word_budget || 0);
}, 0);

const withinTolerance = totalBudgeted >= target * (1 - TOLERANCE) && totalBudgeted <= target * (1 + TOLERANCE);

return [{
  json: {
    role_signal: roleSignal,
    project_order: projectOrder,
    reorder_instructions: reorderInstructions,
    segments_to_edit: toEdit,
    segments_to_skip: toSkip,
    constraint_block: constraintLines,
    edit_count: toEdit.length,
    budget_validation: {
      total_budgeted_words: totalBudgeted,
      target_words: target,
      within_tolerance: withinTolerance,
      delta: totalBudgeted - target
    }
  }
}];

const items = $('Generator').first().json.output.cv_anpassungen;
const classifiedSegments = $('Enforcer').first().json.segments_to_edit;

// Build lookup: original text → classification
const classMap = {};
for (const seg of classifiedSegments) {
  classMap[seg.original.trim()] = {
    classification: seg.classification,
    finalAction: seg.finalAction
  };
}

const valid = [];
const flagged = [];

for (const item of items) {
  // drop "// X -> Y words"
  if (item.neu) {
    item.neu = item.neu.replace(/^\/\/[^\n]*\n?/, '').trim();
  }

  // KÜRZEN with no neu field
  if (item.aktion === 'KÜRZEN' && (!item.neu || item.neu.trim() === '')) {
    continue;
  }

  // 1. No-op detection: ERSETZEN/KÜRZEN with identical text
  if (
    (item.aktion === 'ERSETZEN' || item.aktion === 'KÜRZEN') &&
    item.original.trim() === item.neu.trim()
  ) {
    // Drop silently — no instruction needed
    continue;
  }

  // 2. ENTFERNEN on TRANSFERABEL segment → flag for correction
  const lookup = classMap[item.original.trim()];
  if (
    item.aktion === 'ENTFERNEN' &&
    lookup &&
    lookup.classification === 'TRANSFERABEL'
  ) {
    flagged.push({
      ...item,
      error: 'ENTFERNEN on TRANSFERABEL segment',
      corrected_action: 'KÜRZEN'
    });
    continue;
  }

  // 3. ERSETZEN on DISTRAKTOR (should be ENTFERNEN) → correct silently
  if (
    item.aktion === 'ERSETZEN' &&
    lookup &&
    lookup.classification === 'DISTRAKTOR' &&
    item.neu !== ''
  ) {
    valid.push({ ...item, aktion: 'ENTFERNEN', neu: '' });
    continue;
  }

  valid.push(item);
}

const hasErrors = flagged.length > 0;

return [{
  json: {
    output: { cv_anpassungen: valid },
    flagged,
    has_errors: hasErrors,
    valid_count: valid.length,
    flagged_count: flagged.length
  }
}];

